import React from 'react';
import config from '../../config/site-config';
import Post from '../models/Post';

interface SEOProps {
  postNode?: Post;
  postPath?: string;
  postSEO?: boolean;
  title?: string;
  description?: string;
  image?: string;
  article?: boolean;
}

export function Head({ 
  postNode, 
  postPath, 
  postSEO = false, 
  title: customTitle,
  description: customDescription,
  image: customImage,
  article = false
}: SEOProps) {
  let title: string;
  let description: string;
  let image: string;
  let postURL: string;
  
  const realPrefix = config.pathPrefix === '/' ? '' : config.pathPrefix;
  
  if (postSEO && postNode) {
    const postMeta = postNode.frontmatter;
    title = postMeta.title;
    description = postNode.excerpt;
    image = postMeta.banner || config.siteBanner;
    postURL = config.siteUrl + realPrefix + (postPath || '');
  } else {
    title = customTitle || config.siteTitle;
    description = customDescription || config.siteDescription;
    image = customImage || config.siteBanner;
    postURL = '';
  }
  
  image = image.startsWith('http') ? image : config.siteUrl + realPrefix + image;
  const blogURL = config.siteUrl + config.pathPrefix;
  
  let schemaOrgJSONLD = [
    {
      '@context': 'http://schema.org',
      '@type': 'WebSite',
      '@id': blogURL,
      url: blogURL,
      name: title,
      alternateName: config.siteTitleAlt ? config.siteTitleAlt : '',
      description: description,
      publisher: {
        '@type': 'Person',
        name: config.author,
      },
    },
  ];
  
  if (postSEO && postNode) {
    schemaOrgJSONLD = [
      {
        '@context': 'http://schema.org',
        '@type': 'BlogPosting',
        '@id': postURL,
        url: postURL,
        name: title,
        alternateName: config.siteTitleAlt ? config.siteTitleAlt : '',
        headline: title,
        image: {
          '@type': 'ImageObject',
          url: image,
        },
        description: description,
        datePublished: postNode.frontmatter.date,
        dateModified: postNode.frontmatter.date,
        author: {
          '@type': 'Person',
          name: config.author,
        },
        publisher: {
          '@type': 'Organization',
          name: config.author,
          logo: {
            '@type': 'ImageObject',
            url: config.siteUrl + realPrefix + config.siteLogo,
          },
        },
        isPartOf: blogURL,
        mainEntityOfPage: {
          '@type': 'WebSite',
          '@id': blogURL,
        },
      },
    ];
  }
  
  return (
    <>
      <html lang={config.siteLanguage} />
      <title>{title}</title>
      <meta name="description" content={description} />
      <meta name="image" content={image} />
      
      {/* Canonical URL */}
      <link rel="canonical" href={postSEO ? postURL : blogURL} />
      
      {/* Open Graph / Facebook */}
      <meta property="og:type" content={article ? 'article' : 'website'} />
      <meta property="og:url" content={postSEO ? postURL : blogURL} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={image} />
      <meta property="og:locale" content={config.ogLanguage} />
      <meta property="og:site_name" content={config.ogSiteName || config.siteTitle} />
      {config.siteFBAppID && <meta property="fb:app_id" content={config.siteFBAppID} />}
      
      {/* Twitter */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:creator" content={config.userTwitter || ''} />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={image} />
      <meta name="twitter:url" content={postSEO ? postURL : blogURL} />
      
      {/* Additional SEO meta tags */}
      <meta name="robots" content="index, follow" />
      <meta name="author" content={config.author} />
      <meta name="viewport" content="width=device-width, initial-scale=1" />
      
      {/* Structured Data */}
      <script type="application/ld+json">{JSON.stringify(schemaOrgJSONLD)}</script>
    </>
  );
}

// Keep the old component for backward compatibility
const SEO: React.FC<SEOProps> = (props) => {
  return <div style={{ display: 'none' }} />;
};

export default SEO;
